mapper.select:
SELECT DISTINCT m.* FROM merchant m

    JOIN merchant_category mc ON m.merchant_id = mc.merchant_id



        AND m.merchant_name LIKE CONCAT('%', #{merchantName}, '%')


        AND m.business_number = #{businessNumber}


        AND mc.category_name = #{categoryName}

    AND m.status = 'ACTIVE'

ORDER BY m.created_at DESC
LIMIT #{size} OFFSET #{offset}

