UPDATE merchant
merchant_name = #{dto.merchantName}, representative = #{dto.representative}, contact = #{dto.contact}, address = #{dto.address}, email = #{dto.email}, terminal_id = #{dto.terminalId},
WHERE merchant_id = #{merchantId}
